        Set<String> seen = new HashSet<>();
        String at = sheets.findById(id).map(Sheet::getParent).orElse(null);
        while (at != null && seen.add(at)) {
            if (at.equals(ancestor)) {
                return true;
            }
            at = sheets.findById(at).map(Sheet::getParent).orElse(null);
        }
        return false;
